package posemap

import "testing"

// 本文件为“路标失效的返回结果与地图保存的失效事实相互隔离”这一已有行为
// 提供回归保障。Invalidate 成功时会保存首次操作结果，此后同一操作标识、
// 相同原因、相同路标集合的请求一律返回首次结果。调用方可以自由改写手上
// 的那份返回结果（失效时间、路标标识、出现编号、条目次序），但这些改写
// 只能影响调用方自己的副本：既不能改写地图保存的失效事实与首次结果，也
// 不能影响先后取得的其他副本，更不能让一份合法的重复请求被误判为内容
// 冲突。只使用现有公开入口（ImportSegment/Invalidate/LandmarksInRect/
// LandmarkAppearances），沿用既有错误含义，不改变任何公开使用方式。
//
// 统一场景（初始位姿 (0,0)、朝向 0、合并上限 1）：
//
//	t=100：观测 L 本地 (1,0) → 世界 (1,0)（L 第 1 次出现，计数 1）
//	       观测 M 本地 (2,0) → 世界 (2,0)（M 第 1 次出现，计数 1）
//	t=200：再次观测 L（仍 (1,0)，L 计数 2）
//	t=200 提交失效 op1：撤下 L、M 的第 1 次出现，失效时间 200
//	t=300：DX=10 → 位姿 (10,0)，观测 L 本地 (0,0) → (10,0)（L 第 2 次出现）
//	t=400：DX=5  → 位姿 (15,0)，观测 N 本地 (0,0) → (15,0)（N 第 2 次出现；
//	       N 的第 1 次出现也在 op1 中被撤下）
//
// 即一次失效涉及多个路标，且不同路标的旧出现虽同为编号 1，再现后被验证
// 的路标拥有编号 2——结果与历次出现记录据此区分“被保存的旧编号”和
// “当前有效编号”。

// isolationSetupSeed 是统一场景的初始轨迹：t=100/200 两帧，路标 L、M。
func isolationSetupSeed() Segment {
	return Segment{ID: "s1", Frames: []Frame{
		{Time: 100, Observations: []Observation{{ID: "L", X: 1, Y: 0}, {ID: "M", X: 2, Y: 0}}},
		{Time: 200, Observations: []Observation{{ID: "L", X: 1, Y: 0}}},
	}}
}

// newInvalidationIsolationMap 构造统一场景中“op1 刚成功、路标尚未再现”
// 的地图，便于各用例自行决定是否继续导入再现轨迹。
func newInvalidationIsolationMap(t *testing.T) *Map {
	t.Helper()
	m := newMap(t, Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1.0})
	if _, err := m.ImportSegment(isolationSetupSeed()); err != nil {
		t.Fatalf("seed import: %v", err)
	}
	return m
}

// isolationRequest 是统一场景里的首次失效请求：集合故意以乱序给出，
// 成功结果仍应按标识排列为 L、M。
func isolationRequest() Invalidation {
	return Invalidation{ID: "op1", Reason: "sign removed", Landmarks: []string{"M", "L"}}
}

// snapshotInvalidationResult 在测试侧深拷贝一份失效结果作为期望快照。
// 拷贝逻辑独立于被测实现的 cloneInvalidationResult，避免被测实现退化为
// 浅拷贝时期望值与内部状态共享底层切片、被一并改写而失去对照意义。
func snapshotInvalidationResult(r InvalidationResult) InvalidationResult {
	cp := r
	cp.Landmarks = append([]InvalidatedLandmark(nil), r.Landmarks...)
	return cp
}

// invalidationResultsEqual 断言两份失效结果的时间与逐项内容、次序一致。
func invalidationResultsEqual(a, b InvalidationResult) bool {
	if a.Time != b.Time || len(a.Landmarks) != len(b.Landmarks) {
		return false
	}
	for i := range a.Landmarks {
		if a.Landmarks[i] != b.Landmarks[i] {
			return false
		}
	}
	return true
}

// expectFirstInvalidation 断言一份结果等于首次事实：时间 200，按标识
// 排列的 L、M 两项，且两项指出的都是被撤下的第 1 次出现。
func expectFirstInvalidation(t *testing.T, what string, got InvalidationResult) {
	t.Helper()
	want := InvalidationResult{
		Time: 200,
		Landmarks: []InvalidatedLandmark{
			{ID: "L", Occurrence: 1},
			{ID: "M", Occurrence: 1},
		},
	}
	if !invalidationResultsEqual(got, want) {
		t.Fatalf("%s = %+v, want %+v", what, got, want)
	}
}

// expectInvalidOccurrence 断言某路标的某次出现保留着首次失效的时间与
// 原因，且已不是当前有效记录。
func expectInvalidOccurrence(t *testing.T, id string, ap Appearance) {
	t.Helper()
	if ap.Active {
		t.Fatalf("landmark %s occurrence %d unexpectedly active", id, ap.Number)
	}
	if ap.InvalidTime != 200 || ap.InvalidReason != "sign removed" || ap.InvalidOpID != "op1" {
		t.Fatalf("landmark %s occurrence %d invalid info = %d %q %q, want 200 %q %q",
			id, ap.Number, ap.InvalidTime, ap.InvalidReason, ap.InvalidOpID,
			"sign removed", "op1")
	}
}

// 首次成功返回：一次失效涉及多个路标时结果按标识排列，每项指出实际被
// 撤下的出现编号，且集合中不同路标都在结果里。
func TestInvalidateFirstResultOrderAndOccurrences(t *testing.T) {
	m := newInvalidationIsolationMap(t)
	first, err := m.Invalidate(isolationRequest())
	if err != nil {
		t.Fatalf("first Invalidate: %v", err)
	}
	expectFirstInvalidation(t, "first result", first)

	// 被撤下的两次出现都在历次出现记录中保留原始失效时间与原因；区域
	// 查询立即把两者排除。
	for _, id := range []string{"L", "M"} {
		h, err := m.LandmarkAppearances(id)
		if err != nil {
			t.Fatalf("history %s: %v", id, err)
		}
		if len(h.Appearances) != 1 || h.Appearances[0].Number != 1 {
			t.Fatalf("history %s = %+v, want single occurrence 1", id, h.Appearances)
		}
		expectInvalidOccurrence(t, id, h.Appearances[0])
	}
	if lms, _ := m.LandmarksInRect(allRect()); len(lms) != 0 {
		t.Fatalf("invalidated landmarks still in region query: %v", lms)
	}
}

// 调用方改写首次返回的失效时间、路标标识、出现编号并调换条目次序后，
// 用原来的操作内容重复提交：得到的仍是原始时间、完整集合与正确编号，
// 既不带入被修改的内容，也不漏掉其他条目。
func TestInvalidateDuplicateResultIsolatedFromFirstMutation(t *testing.T) {
	m := newInvalidationIsolationMap(t)
	req := isolationRequest()
	first, err := m.Invalidate(req)
	if err != nil {
		t.Fatalf("first Invalidate: %v", err)
	}
	want := snapshotInvalidationResult(first)

	// ---- 就地改写调用方手上的首次结果：时间、标识、编号，再调换次序 ----
	first.Time = -77
	first.Landmarks[0].ID = "ZZ"
	first.Landmarks[0].Occurrence = 99
	first.Landmarks[1].ID = ""
	first.Landmarks[1].Occurrence = -3
	first.Landmarks[0], first.Landmarks[1] = first.Landmarks[1], first.Landmarks[0]

	// 原操作内容（同标识、同原因、同集合，集合仍按乱序给出）重复提交：
	// 返回首次保存的事实，改写内容一个都不能出现，L、M 两项都不能少。
	again, err := m.Invalidate(req)
	if err != nil {
		t.Fatalf("duplicate Invalidate after mutating first result: %v", err)
	}
	if !invalidationResultsEqual(again, want) {
		t.Fatalf("duplicate result = %+v, want saved first %+v", again, want)
	}
	expectFirstInvalidation(t, "duplicate result", again)

	// 地图保存的失效事实同样没被改写：两次旧出现仍是编号 1、时间 200、
	// 原因 sign removed。
	for _, id := range []string{"L", "M"} {
		h, err := m.LandmarkAppearances(id)
		if err != nil {
			t.Fatalf("history %s: %v", id, err)
		}
		if len(h.Appearances) != 1 || h.Appearances[0].Number != 1 {
			t.Fatalf("history %s = %+v", id, h.Appearances)
		}
		expectInvalidOccurrence(t, id, h.Appearances[0])
	}
}

// 重复提交得到的结果也是独立副本：改写其中一项，先前保留的另一份返回
// 结果不跟着变化；此后再次取得的结果仍与首次保存的事实一致。同一请求
// 的路标列表换一种先后顺序仍是相同集合，返回次序继续按标识排列，不能
// 因为调用方修改过上一次的输出就把合法重复请求误判为内容冲突。
func TestInvalidateDuplicateCopiesIndependent(t *testing.T) {
	m := newInvalidationIsolationMap(t)
	first, err := m.Invalidate(isolationRequest())
	if err != nil {
		t.Fatalf("first Invalidate: %v", err)
	}
	want := snapshotInvalidationResult(first)

	// 第一份重复结果（集合以另一种次序给出：集合语义，与次序无关）。
	copyA, err := m.Invalidate(Invalidation{
		ID: "op1", Reason: "sign removed", Landmarks: []string{"L", "M"},
	})
	if err != nil {
		t.Fatalf("duplicate with reordered set rejected: %v", err)
	}
	if !invalidationResultsEqual(copyA, want) {
		t.Fatalf("copyA = %+v, want first result %+v", copyA, want)
	}

	// 调用方只改写 copyA 中的一项。
	copyA.Time = -1
	copyA.Landmarks[0].ID = "tampered"
	copyA.Landmarks[0].Occurrence = 424

	// 先前保留的首次结果不跟着变化。
	if !invalidationResultsEqual(first, want) {
		t.Fatalf("earlier result changed after editing another copy: %+v", first)
	}

	// 再次取得的结果仍是首次事实：即便上次输出被改成陌生标识/编号，
	// 合法的重复请求也不会被误判为 invalidation_mismatch。
	copyB, err := m.Invalidate(isolationRequest())
	if err != nil {
		t.Fatalf("second duplicate after mutating copyA: %v", err)
	}
	if !invalidationResultsEqual(copyB, want) {
		t.Fatalf("copyB = %+v, want first result %+v", copyB, want)
	}

	// 再改写 copyB 中的另一项，先前两份结果同样不受影响。
	copyB.Landmarks[1].ID = "also-tampered"
	copyB.Landmarks[1].Occurrence = -9
	copyB.Landmarks = append(copyB.Landmarks, InvalidatedLandmark{ID: "EXTRA", Occurrence: 7})
	if !invalidationResultsEqual(first, want) {
		t.Fatalf("first result changed after editing copyB: %+v", first)
	}
	if !invalidationResultsEqual(copyA[:len(want.Landmarks)] == copyA[:len(want.Landmarks)], InvalidationResult{}) || false {
		t.Fatal("unreachable")
	}
	copyC, err := m.Invalidate(Invalidation{
		ID: "op1", Reason: "sign removed", Landmarks: []string{"M", "L"},
	})
	if err != nil {
		t.Fatalf("third duplicate: %v", err)
	}
	if !invalidationResultsEqual(copyC, want) {
		t.Fatalf("copyC = %+v, want first result %+v (saved fact polluted)", copyC, want)
	}
}

// 原操作涉及的路标后来再次出现：首次结果中的编号仍指向已经失效的旧
// 出现，不会被替换成当前有效出现的编号；即使调用方把拿到的旧结果改成
// 新编号，再提交原操作也不能撤下新出现。区域查询仍包含新出现，历次
// 出现查询保留旧记录的失效时间和原因；未再次出现的路标继续被区域查询
// 排除。
func TestInvalidateDuplicateKeepsStaleOccurrenceAfterReappearance(t *testing.T) {
	m := newInvalidationIsolationMap(t)
	first, err := m.Invalidate(isolationRequest())
	if err != nil {
		t.Fatalf("first Invalidate: %v", err)
	}
	want := snapshotInvalidationResult(first)

	// L 在 t=300 再现为第 2 次出现（位姿 (10,0)，世界坐标 (10,0)）；
	// N 在 t=400 再现为第 2 次出现（位姿 (15,0)，世界坐标 (15,0)）。
	// M 不再出现。
	if _, err := m.ImportSegment(Segment{ID: "s2", Frames: []Frame{
		{Time: 300, DX: 10, Observations: []Observation{{ID: "L"}}},
	}}); err != nil {
		t.Fatalf("L reappearance: %v", err)
	}
	if _, err := m.ImportSegment(Segment{ID: "s3", Frames: []Frame{
		{Time: 400, DX: 5, Observations: []Observation{{ID: "N", X: 0, Y: 0}}},
	}}); err != nil {
		t.Fatalf("N reappearance: %v", err)
	}

	// 再现后区域查询只含当前有效出现 L occ2、N occ2；M 未再现，继续排除。
	lms := activeLandmarks(t, m)
	if len(lms) != 2 {
		t.Fatalf("active landmarks = %v, want only reappeared L and N", lms)
	}
	if lL, ok := lms["L"]; !ok || lL.Count != 1 {
		t.Fatalf("active L = %+v ok=%v, want occurrence 2 count 1", lL, ok)
	} else {
		approxEq(t, "active L x", lL.X, 10)
	}
	if lN, ok := lms["N"]; !ok || lN.Count != 1 {
		t.Fatalf("active N = %+v ok=%v, want occurrence 2 count 1", lN, ok)
	} else {
		approxEq(t, "active N x", lN.X, 15)
	}
	if _, ok := lms["M"]; ok {
		t.Fatalf("non-reappeared M back in region query: %+v", lms["M"])
	}

	// 历次出现记录：L、N 各有两次，旧出现保留原失效时间与原因，新出现
	// 有效且编号为 2；M 只有失效的第 1 次。
	hL, _ := m.LandmarkAppearances("L")
	if len(hL.Appearances) != 2 {
		t.Fatalf("L history = %+v, want two occurrences", hL.Appearances)
	}
	expectInvalidOccurrence(t, "L", hL.Appearances[0])
	if !hL.Appearances[1].Active || hL.Appearances[1].Number != 2 ||
		hL.Appearances[1].Landmark.Count != 1 || !hL.Appearances[1].HasFirstSeen ||
		hL.Appearances[1].FirstSeenTime != 300 {
		t.Fatalf("L occurrence 2 = %+v, want active occurrence first seen at 300", hL.Appearances[1])
	}
	hN, _ := m.LandmarkAppearances("N")
	if len(hN.Appearances) != 2 {
		t.Fatalf("N history = %+v, want two occurrences", hN.Appearances)
	}
	expectInvalidOccurrence(t, "N", hN.Appearances[0])
	if !hN.Appearances[1].Active || hN.Appearances[1].Number != 2 ||
		hN.Appearances[1].FirstSeenTime != 400 {
		t.Fatalf("N occurrence 2 = %+v", hN.Appearances[1])
	}
	hM, _ := m.LandmarkAppearances("M")
	if len(hM.Appearances) != 1 {
		t.Fatalf("M history = %+v, want only invalidated occurrence 1", hM.Appearances)
	}
	expectInvalidOccurrence(t, "M", hM.Appearances[0])

	// 调用方把拿到的旧结果改成“当前有效编号”（2），并改掉时间与标识，
	// 试图让重复提交撤下新出现。
	tampered := snapshotInvalidationResult(first)
	tampered.Time = 400
	tampered.Landmarks[0].Occurrence = 2 // L：旧出现编号被改成新出现编号
	tampered.Landmarks[1].Occurrence = 2 // M：M 根本没有第 2 次出现
	tampered.Landmarks[0].ID = "L"
	tampered.Landmarks[1].ID = "M"

	// 用原来的操作内容重复提交：结果仍保存旧事实（时间 200、编号 1），
	// 不因调用方手上的篡改而撤下任何新出现。
	again, err := m.Invalidate(isolationRequest())
	if err != nil {
		t.Fatalf("duplicate after reappearance: %v", err)
	}
	if !invalidationResultsEqual(again, want) {
		t.Fatalf("duplicate after reappearance = %+v, want stale first result %+v", again, want)
	}
	_ = tampered

	// L、N 的新出现仍然有效，区域查询结果不变；旧出现失效信息不变。
	lms = activeLandmarks(t, m)
	if len(lms) != 2 {
		t.Fatalf("active landmarks after duplicate = %v, want L and N still active", lms)
	}
	if _, ok := lms["L"]; !ok {
		t.Fatalf("new L occurrence was taken down by duplicate: %v", lms)
	}
	if _, ok := lms["N"]; !ok {
		t.Fatalf("new N occurrence was taken down by duplicate: %v", lms)
	}
	hL2, _ := m.LandmarkAppearances("L")
	if len(hL2.Appearances) != 2 || hL2.Appearances[0].Active || !hL2.Appearances[1].Active {
		t.Fatalf("L occurrences changed by duplicate: %+v", hL2.Appearances)
	}
	if hL2.Appearances[0].InvalidTime != 200 || hL2.Appearances[0].OccurrenceFieldSafe() {
		t.Fatalf("L old occurrence invalid info changed: %+v", hL2.Appearances[0])
	}
}

// 同一操作标识换了原因或换了路标集合，仍以 invalidation_mismatch 拒绝，
// 且拒绝不改变此前的结果隔离关系与有效/失效状态：先前取得的结果保持
// 原样，原操作随后重复提交仍返回首次事实，再现的新出现继续有效。
func TestInvalidateMismatchAfterMutatedDuplicatesPreservesState(t *testing.T) {
	m := newInvalidationIsolationMap(t)
	first, err := m.Invalidate(isolationRequest())
	if err != nil {
		t.Fatalf("first Invalidate: %v", err)
	}
	want := snapshotInvalidationResult(first)

	// L 再现为当前有效的第 2 次出现；M 未再现。
	if _, err := m.ImportSegment(Segment{ID: "s2", Frames: []Frame{
		{Time: 300, DX: 10, Observations: []Observation{{ID: "L"}}},
	}}); err != nil {
		t.Fatalf("reappearance: %v", err)
	}

	// 先取一份重复结果并彻底改写，制造“合法重复请求可能被上次输出污染”
	// 的前提。
	dup, err := m.Invalidate(isolationRequest())
	if err != nil {
		t.Fatalf("duplicate before mismatch: %v", err)
	}
	dup.Time = -5
	dup.Landmarks[0].ID = "ZZ"
	dup.Landmarks[0].Occurrence = 333
	dup.Landmarks[1].ID = "QQ"
	dup.Landmarks[1].Occurrence = 666
	dup.Landmarks = append(dup.Landmarks, InvalidatedLandmark{ID: "EXTRA", Occurrence: 1})

	expectMismatch := func(req Invalidation) {
		t.Helper()
		_, err := m.Invalidate(req)
		r, ok := AsRejectError(err)
		if !ok || r.Kind != RejectInvalidationMismatch ||
			!r.HasLandmark || r.Landmark != "op1" {
			t.Fatalf("mismatch request %+v: err = %v, want invalidation_mismatch for op1", req, err)
		}
	}

	// 同标识换原因。
	expectMismatch(Invalidation{ID: "op1", Reason: "other reason", Landmarks: []string{"M", "L"}})
	// 同标识换路标集合（增、减、换成别的路标）。
	expectMismatch(Invalidation{ID: "op1", Reason: "sign removed", Landmarks: []string{"M"}})
	expectMismatch(Invalidation{ID: "op1", Reason: "sign removed", Landmarks: []string{"L", "M", "N"}})
	expectMismatch(Invalidation{ID: "op1", Reason: "sign removed", Landmarks: []string{"L"}})

	// 先前保留的首次结果未被任何拒绝改变。
	if !invalidationResultsEqual(first, want) {
		t.Fatalf("first result changed after mismatch rejections: %+v", first)
	}
	// 原操作内容重复提交仍返回首次事实（时间 200、编号 1、两项齐全）。
	again, err := m.Invalidate(isolationRequest())
	if err != nil {
		t.Fatalf("original request after mismatches: %v", err)
	}
	if !invalidationResultsEqual(again, want) {
		t.Fatalf("result after mismatches = %+v, want first result %+v", again, want)
	}

	// 有效/失效状态不变：L 的新出现仍有效，旧出现保留原失效事实；M 仍
	// 只有失效的第 1 次出现；区域查询只含 L。
	lms := activeLandmarks(t, m)
	if len(lms) != 1 {
		t.Fatalf("active landmarks = %v, want only reappeared L", lms)
	}
	if lL := lms[0]; lL.ID != "L" || lL.Count != 1 {
		t.Fatalf("active landmark = %+v, want L occurrence 2", lL)
	}
	hL, _ := m.LandmarkAppearances("L")
	if len(hL.Appearances) != 2 || hL.Appearances[0].Active || !hL.Appearances[1].Active {
		t.Fatalf("L occurrences after mismatches = %+v", hL.Appearances)
	}
	expectInvalidOccurrence(t, "L", hL.Appearances[0])
	hM, _ := m.LandmarkAppearances("M")
	if len(hM.Appearances) != 1 || hM.Appearances[0].Active {
		t.Fatalf("M occurrences after mismatches = %+v, want single invalid occurrence", hM.Appearances)
	}
	expectInvalidOccurrence(t, "M", hM.Appearances[0])
}

